use crate::aap::caps::{http_client, notifier};

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set, so the
/// enrichment query value cannot alter the URL's structure.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch, per the platform team's approved change. Its result
        // does not feed the output, so the published digest is unaffected.
        // The "input's text" is taken to be the digest overview, the only
        // free-text field on the input. A transport failure comes back as a
        // value and is ignored; an allowlist refusal traps at the boundary.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&enrich_url);

        let message = format!("Digest {}\n{}", composed.date, composed.overview);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
